import 'jsr:@supabase/functions-js/edge-runtime.d.ts';

import { createClient } from 'jsr:@supabase/supabase-js@2';

import {
  flowerCountFromLeafArea,
  pollenIntervalElapsed,
  pollenVolumeCm3,
} from '../_shared/flower-pollen.ts';
import { getPlantStatus, type LatestObservation } from '../_shared/plant-status.ts';

const POLLEN_ACCRUAL_SECRET = 'kR7mQ2vL9pX4nW8sT1cY6bH3dF5aJ0eU';

type PlantRow = {
  id: string;
  user_id: string;
  flower_ratio: number | null;
  pollen_per_flower_cm3: number | null;
  last_pollen_credited_at: string | null;
};

type HealthRow = LatestObservation & { plant_id: string };

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

function authorized(req: Request) {
  const header = req.headers.get('Authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice('Bearer '.length) : '';
  const secret = Deno.env.get('POLLEN_ACCRUAL_SECRET')?.trim() || POLLEN_ACCRUAL_SECRET;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? Deno.env.get('SUPABASE_SECRET_KEY');
  return token.length > 0 && (token === secret || token === serviceKey);
}

Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') {
    return json({ error: 'Method not allowed' }, 405);
  }
  if (!authorized(req)) {
    return json({ error: 'Unauthorized' }, 401);
  }

  const url = Deno.env.get('SUPABASE_URL');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? Deno.env.get('SUPABASE_SECRET_KEY');
  if (!url || !serviceKey) {
    return json({ error: 'Supabase environment is not configured' }, 500);
  }

  const admin = createClient(url, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const now = new Date();

  const { data: plantRows, error: plantError } = await admin
    .from('plants')
    .select('id, user_id, flower_ratio, pollen_per_flower_cm3, last_pollen_credited_at')
    .not('flower_ratio', 'is', null);

  if (plantError) {
    return json({ error: plantError.message }, 500);
  }

  const plants = (plantRows ?? []) as PlantRow[];
  if (plants.length === 0) {
    return json({ updated: 0, credited: 0 });
  }

  const { data: healthRows, error: healthError } = await admin
    .from('plant_health_info')
    .select(
      'plant_id, observed_at, resolved_x_position, estimated_health_score, growth_mode, l, k, x0, xg, kg, ks, xs, f, r, cycle_length, b_base, l_season'
    )
    .in('plant_id', plants.map((plant) => plant.id))
    .order('observed_at', { ascending: false });

  if (healthError) {
    return json({ error: healthError.message }, 500);
  }

  const latest = new Map<string, HealthRow>();
  for (const row of (healthRows ?? []) as HealthRow[]) {
    if (!latest.has(row.plant_id)) {
      latest.set(row.plant_id, row);
    }
  }

  const credits = new Map<string, number>();
  let updated = 0;
  let credited = 0;

  for (const plant of plants) {
    const status = getPlantStatus(null, null, latest.get(plant.id) ?? null, now);
    const flowers = flowerCountFromLeafArea(status?.leafAreaCm2 ?? 0, plant.flower_ratio ?? 0);
    const plantUpdate: Record<string, unknown> = {
      flower_count: flowers,
      flower_count_updated_at: now.toISOString(),
    };

    const due = plant.last_pollen_credited_at == null || pollenIntervalElapsed(plant.last_pollen_credited_at, now);
    if (due) {
      plantUpdate.last_pollen_credited_at = now.toISOString();
      if (plant.last_pollen_credited_at != null) {
        const volume = pollenVolumeCm3(flowers, plant.pollen_per_flower_cm3 ?? 0);
        if (volume > 0) {
          credits.set(plant.user_id, (credits.get(plant.user_id) ?? 0) + volume);
        }
        credited += 1;
      }
    }

    const { error: updateError } = await admin.from('plants').update(plantUpdate).eq('id', plant.id);
    if (updateError) {
      console.error(`accrue-pollen: plant ${plant.id}: ${updateError.message}`);
      continue;
    }
    updated += 1;
  }

  for (const [userId, amount] of credits) {
    const { error: creditError } = await admin.rpc('credit_user_pollen', {
      target_user_id: userId,
      amount,
    });
    if (creditError) {
      console.error(`accrue-pollen: credit ${userId}: ${creditError.message}`);
    }
  }

  return json({ updated, credited, users: credits.size });
});

import { lowercaseKeys } from './json-utils.ts';

// Flower ratio and pollen-per-flower are constants, not a growth curve.
// A photo asks Gemini to correct the previous constants. The hourly accrual
// job multiplies flower_ratio by current leaf area; it does not call the LLM.

export type FlowerPollenConstants = {
  /** Flowers per cm² of leaf area. 0 means the plant is not flowering. */
  flower_ratio: number;
  /** Cubic centimeters of pollen one flower produces over 8 hours. */
  pollen_per_flower_cm3: number;
};

const GEMINI_API_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';
const DEFAULT_GEMINI_MODEL = 'gemini-3.1-flash-lite';

const POLLEN_INTERVAL_HOURS = 8;

export function flowerCountFromLeafArea(leafAreaCm2: number, flowerRatio: number) {
  if (!Number.isFinite(leafAreaCm2) || leafAreaCm2 <= 0 || !Number.isFinite(flowerRatio) || flowerRatio <= 0) {
    return 0;
  }
  return leafAreaCm2 * flowerRatio;
}

export function pollenVolumeCm3(flowerCount: number, pollenPerFlowerCm3: number) {
  if (!Number.isFinite(flowerCount) || flowerCount <= 0 || !Number.isFinite(pollenPerFlowerCm3) || pollenPerFlowerCm3 <= 0) {
    return 0;
  }
  return flowerCount * pollenPerFlowerCm3;
}

export function pollenIntervalElapsed(lastCreditedAt: string | null, now: Date) {
  if (!lastCreditedAt) {
    return false;
  }
  const at = new Date(lastCreditedAt).getTime();
  if (!Number.isFinite(at)) {
    return false;
  }
  return now.getTime() - at >= POLLEN_INTERVAL_HOURS * 60 * 60 * 1000;
}

function buildPrompt(
  scientificName: string | null,
  commonName: string | null,
  previous: FlowerPollenConstants | null
): string {
  const species = scientificName?.trim() || 'Unknown';
  const common = commonName?.trim() || 'Unknown';
  const previousText = previous
    ? `Previous constants for this plant: flower_ratio=${previous.flower_ratio}, pollen_per_flower_cm3=${previous.pollen_per_flower_cm3}. CORRECT them from this photo. These are constants, not a curve. If the plant looks about the same, keep both numbers close to the previous values. Change them only when the photo clearly shows more flowers, fewer flowers, or a different pollen yield.`
    : 'This plant has no previous constants. Estimate them from the species and what you can see in the photo.';

  return `You are looking at a photo of a plant (species: ${species}, common name: ${common}).

Estimate two constants for pollen the plant produces. Do not estimate leaf area or a growth curve.

- flower_ratio: number of flowers per cm² of leaf area. 0 if the plant has no flowers. A typical garden plant in bloom is about 0.001 to 0.05.
- pollen_per_flower_cm3: cubic centimeters of pollen one open flower produces over ${POLLEN_INTERVAL_HOURS} hours. 0 if there are no flowers. Typical values are about 0.01 to 2.

${previousText}

Return only valid JSON: {"flower_ratio": number, "pollen_per_flower_cm3": number}`;
}

function asFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

export function validateFlowerPollenConstants(raw: unknown): FlowerPollenConstants | null {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const record = raw as Record<string, unknown>;
  const flowerRatio = asFiniteNumber(record.flower_ratio);
  const pollenPerFlower = asFiniteNumber(record.pollen_per_flower_cm3);
  if (flowerRatio == null || flowerRatio < 0 || flowerRatio > 1) {
    return null;
  }
  if (pollenPerFlower == null || pollenPerFlower < 0 || pollenPerFlower > 20) {
    return null;
  }
  if (flowerRatio === 0) {
    return { flower_ratio: 0, pollen_per_flower_cm3: 0 };
  }
  return { flower_ratio: flowerRatio, pollen_per_flower_cm3: pollenPerFlower };
}

export async function generateFlowerPollenParams(
  imageBase64: string,
  mimeType: string,
  scientificName: string | null,
  commonName: string | null,
  previous: FlowerPollenConstants | null
): Promise<FlowerPollenConstants | null> {
  try {
    const apiKey = Deno.env.get('GEMINI_KEY');
    if (!apiKey) {
      console.error('GEMINI_KEY is not set; skipping flower and pollen constants');
      return null;
    }

    const model = Deno.env.get('GEMINI_MODEL')?.trim() || DEFAULT_GEMINI_MODEL;
    const url = `${GEMINI_API_BASE}/${model}:generateContent?key=${encodeURIComponent(apiKey)}`;
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              { inline_data: { mime_type: mimeType, data: imageBase64 } },
              { text: buildPrompt(scientificName, commonName, previous) },
            ],
          },
        ],
        generationConfig: { responseMimeType: 'application/json' },
      }),
    });

    if (!response.ok) {
      console.error(`Flower pollen Gemini request failed (${response.status})`);
      return null;
    }

    const payload = await response.json().catch(() => null);
    const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (typeof text !== 'string' || text.trim().length === 0) {
      return null;
    }

    const parsed = JSON.parse(text);
    const normalized = typeof parsed === 'object' && parsed !== null ? lowercaseKeys(parsed) : parsed;
    const validated = validateFlowerPollenConstants(normalized);
    if (!validated) {
      console.error('FLOWER_POLLEN_DEBUG: validation rejected', text);
    }
    return validated;
  } catch (error) {
    console.error('generateFlowerPollenParams failed:', error);
    return null;
  }
}

export function lowercaseKeys(obj: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) {
    result[key.toLowerCase()] = obj[key];
  }
  return result;
}

import { evaluateGrowthCurve, type GrowthCurveParams, type GrowthMode } from './growth-curve.ts';

// Derives a plant's current status from its latest plant_health_info row by
// advancing that row's curve position by the time elapsed since it was
// observed ("curve age"): x = resolved_x_position + days since observed_at.
// Every function here is best-effort and returns null instead of throwing.

/** The slice of a plant_health_info row this module reads. */
export type LatestObservation = {
  observed_at: string;
  resolved_x_position: number | null;
  estimated_health_score: number | null;
  growth_mode: GrowthMode | null;
  l: number | null;
  k: number | null;
  x0: number | null;
  xg: number | null;
  kg: number | null;
  ks?: number | null;
  xs?: number | null;
  f?: number | null;
  r?: number | null;
  cycle_length?: number | null;
  b_base?: number | null;
  l_season?: number | null;
};

export type PlantStatus = {
  leafAreaCm2: number;
  healthScore: number;
};

/**
 * PLACEHOLDER health score (0-100, same scale as estimated_health_score) used
 * when an observation has none, e.g. a baseline row seeded at add time before
 * any photo has been analyzed. Not a real measurement; replace once there is a
 * better default.
 */
export const DEFAULT_HEALTH_SCORE = 70;

const MS_PER_DAY = 86_400_000;

/** Fractional days from `from` to `to`; null if `from` isn't a valid date. */
export function daysElapsed(from: string, to: Date): number | null {
  const fromMs = new Date(from).getTime();
  const days = (to.getTime() - fromMs) / MS_PER_DAY;
  return Number.isFinite(days) ? days : null;
}

/** Growth-curve params from a plant_health_info row, or null if any required one is missing. */
export function paramsFromObservation(row: LatestObservation): GrowthCurveParams | null {
  if (!row.growth_mode || row.l == null || row.k == null || row.x0 == null || row.xg == null || row.kg == null) {
    return null;
  }

  return {
    growth_mode: row.growth_mode,
    l: row.l,
    k: row.k,
    x0: row.x0,
    xg: row.xg,
    kg: row.kg,
    ks: row.ks,
    xs: row.xs,
    f: row.f,
    r: row.r,
    cycle_length: row.cycle_length,
    b_base: row.b_base,
    l_season: row.l_season,
  };
}

/** The row's curve position advanced to `now`; null if the position or date is unusable. */
export function currentCurveX(resolvedXPosition: number | null, observedAt: string, now: Date): number | null {
  if (resolvedXPosition == null || !Number.isFinite(resolvedXPosition)) {
    return null;
  }
  const elapsed = daysElapsed(observedAt, now);
  return elapsed == null ? null : resolvedXPosition + Math.max(0, elapsed);
}

/**
 * What a previously fitted curve predicts the plant's fullness is at `now`, as
 * a percentage (evaluateGrowthCurve / l * 100, rounded to 0.1). Null if the
 * position or params are missing or the curve can't be evaluated.
 */
export function predictFullnessPct(
  params: GrowthCurveParams | null,
  resolvedXPosition: number | null,
  observedAt: string,
  now: Date
): number | null {
  try {
    if (!params) {
      return null;
    }
    const x = currentCurveX(resolvedXPosition, observedAt, now);
    if (x == null) {
      return null;
    }
    const pct = (evaluateGrowthCurve(params, x) / params.l) * 100;
    return Number.isFinite(pct) ? Math.round(pct * 10) / 10 : null;
  } catch {
    return null;
  }
}

/**
 * Current estimated leaf area and health for a plant, from its latest
 * plant_health_info row. Returns null if there is no observation or the row's
 * params or position are missing. Never throws.
 *
 * `plant` and `basicInfo` are accepted for call-site symmetry but unused: a
 * row's resolved_x_position is only meaningful against that same row's params,
 * so species params are deliberately not substituted.
 */
export function getPlantStatus(
  _plant: unknown,
  _basicInfo: unknown,
  latestObservation: LatestObservation | null | undefined,
  now: Date
): PlantStatus | null {
  try {
    if (!latestObservation) {
      return null;
    }
    const params = paramsFromObservation(latestObservation);
    if (!params) {
      return null;
    }
    const x = currentCurveX(latestObservation.resolved_x_position, latestObservation.observed_at, now);
    if (x == null) {
      return null;
    }
    const leafAreaCm2 = evaluateGrowthCurve(params, x);
    if (!Number.isFinite(leafAreaCm2)) {
      return null;
    }
    return { leafAreaCm2, healthScore: latestObservation.estimated_health_score ?? DEFAULT_HEALTH_SCORE };
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Inline tests: deno run supabase/functions/_shared/plant-status.ts
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const check = (name: string, pass: boolean, detail: unknown) =>
    console.log(`[${pass ? 'PASS' : 'FAIL'}] ${name}: ${JSON.stringify(detail)}`);

  const now = new Date('2026-10-12T00:00:00Z');
  const observedAt = '2026-10-02T00:00:00Z'; // 10 days earlier
  const row: LatestObservation = {
    observed_at: observedAt,
    resolved_x_position: 100,
    estimated_health_score: 0.8,
    growth_mode: 'woody_residual',
    l: 1000,
    k: 0.05,
    x0: 120,
    xg: 45,
    kg: 0.2,
    xs: 200,
    r: 2,
  };
  const params = paramsFromObservation(row)!;

  const status = getPlantStatus(null, null, row, now);
  check('leaf area uses x = resolved_x_position + 10 days', status?.leafAreaCm2 === evaluateGrowthCurve(params, 110), status);
  check('health score comes from the row', status?.healthScore === 0.8, status?.healthScore);
  check('no observation -> null', getPlantStatus(null, null, null, now) === null, null);
  const noScore = getPlantStatus(null, null, { ...row, estimated_health_score: null }, now);
  check('missing health score -> DEFAULT_HEALTH_SCORE', noScore?.healthScore === DEFAULT_HEALTH_SCORE, noScore);
  check('missing params -> null', getPlantStatus(null, null, { ...row, l: null }, now) === null, null);
  check('missing position -> null', getPlantStatus(null, null, { ...row, resolved_x_position: null }, now) === null, null);
  check('missing mode param -> null, no throw', getPlantStatus(null, null, { ...row, xs: null }, now) === null, null);
  check('bad observed_at -> null', getPlantStatus(null, null, { ...row, observed_at: 'nope' }, now) === null, null);

  const expectedPct = Math.round((evaluateGrowthCurve(params, 110) / params.l) * 1000) / 10;
  check('predictFullnessPct matches the curve', predictFullnessPct(params, 100, observedAt, now) === expectedPct, expectedPct);
  check('predictFullnessPct null without position', predictFullnessPct(params, null, observedAt, now) === null, null);
  check('predictFullnessPct null without params', predictFullnessPct(null, 100, observedAt, now) === null, null);
}

// Growth-curve model for estimating a plant's leaf area over time.
//
// y(x) = L · G(x) · P(x) · M(x)
//
//   G(x) — germination/emergence gate (logistic, ramps 0 -> 1 around xg)
//   P(x) — main logistic growth term (ramps 0 -> 1 around x0)
//   M(x) — growth-mode-specific modifier (see GrowthMode below)
//
// Column names below intentionally mirror public.plant_basic_info
// (see supabase/migrations/20260913054225_add_growth_curve_params.sql)
// so a row from that table can be passed in directly.

export type GrowthMode = 'annual_bounded' | 'woody_residual' | 'cyclical';

export type GrowthCurveParams = {
  growth_mode: GrowthMode;
  /** Peak/mature leaf area (cm²) — carrying capacity. */
  l: number;
  /** Growth rate constant for the main logistic term P(x). */
  k: number;
  /** Day of maximum growth rate (inflection point) in P(x). */
  x0: number;
  /** Germination/emergence midpoint day, used in G(x). */
  xg: number;
  /** Germination steepness constant, used in G(x). */
  kg: number;

  // annual_bounded only
  /** Steepness constant for the senescence term (distinct from k). */
  ks?: number | null;
  /** Senescence onset day. */
  xs?: number | null;
  /** Long-term canopy retention floor, as a fraction of L. */
  f?: number | null;

  // woody_residual only
  /** Residual growth rate (cm²/day) added after xs. */
  r?: number | null;
  // woody_residual reuses `xs` above as the residual-growth start day.

  // cyclical only
  /** Days per growth cycle (e.g. ~365 for annual die-back perennials). */
  cycle_length?: number | null;
  /** Persistent crown/root leaf-area baseline (cm²) that survives dormancy. */
  b_base?: number | null;
  /** New seasonal leaf area regrown each cycle (cm²). */
  l_season?: number | null;
};

function requireParam(value: number | null | undefined, name: string, growthMode: GrowthMode): number {
  if (value == null || !Number.isFinite(value)) {
    throw new Error(`growth_mode '${growthMode}' requires numeric param '${name}'`);
  }
  return value;
}

function logistic(steepness: number, x: number, midpoint: number): number {
  return 1 / (1 + Math.exp(-steepness * (x - midpoint)));
}

/** Modulo that always returns a value in [0, modulus), unlike JS `%`. */
function positiveMod(value: number, modulus: number): number {
  return ((value % modulus) + modulus) % modulus;
}

function evaluateM(params: GrowthCurveParams, x: number): number {
  switch (params.growth_mode) {
    case 'annual_bounded': {
      const ks = requireParam(params.ks, 'ks', params.growth_mode);
      const xs = requireParam(params.xs, 'xs', params.growth_mode);
      const f = requireParam(params.f, 'f', params.growth_mode);
      return 1 - (1 - f) / (1 + Math.exp(-ks * (x - xs)));
    }

    case 'woody_residual': {
      const r = requireParam(params.r, 'r', params.growth_mode);
      const xs = requireParam(params.xs, 'xs', params.growth_mode);
      return 1 + (r * Math.max(0, x - xs)) / params.l;
    }

    case 'cyclical': {
      const cycleLength = requireParam(params.cycle_length, 'cycle_length', params.growth_mode);
      const bBase = requireParam(params.b_base, 'b_base', params.growth_mode);
      const lSeason = requireParam(params.l_season, 'l_season', params.growth_mode);
      const xSeason = positiveMod(x, cycleLength);
      return bBase / params.l + (lSeason / params.l) * logistic(params.k, xSeason, params.x0);
    }

    default: {
      const exhaustive: never = params.growth_mode;
      throw new Error(`Unknown growth_mode: ${String(exhaustive)}`);
    }
  }
}

export function evaluateGrowthCurve(params: GrowthCurveParams, x: number): number {
  const g = logistic(params.kg, x, params.xg);
  const p = logistic(params.k, x, params.x0);
  const m = evaluateM(params, x);
  return params.l * g * p * m;
}

export type SolveXForFullnessOptions = {
  /** Lower bound of the search range, in days. Defaults to 0. */
  minX?: number;
  /**
   * Upper bound of the search range, in days. Defaults to cycle_length for
   * 'cyclical' plants and 3650 (10 years) otherwise.
   */
  maxX?: number;
  /** Stop bisecting once the bracket width is at most this many days. Defaults to 0.01. */
  toleranceX?: number;
  /** Max bisection iterations, as a backstop against a non-converging search. */
  maxIterations?: number;
};

const SOLVE_SCAN_STEP_DAYS = 0.5;

/**
 * Finds x such that evaluateGrowthCurve(params, x) / params.l ≈ fullnessPct / 100.
 *
 * Works for curves that rise and fall (annual_bounded after senescence,
 * cyclical): it scans forward from minX in 0.5-day steps, finds the first day
 * whose fullness reaches the target, then bisects between the last day below
 * the target and that day. For 'cyclical' plants only [0, cycle_length] is
 * scanned, i.e. the first cycle. If no scanned day reaches the target, it
 * returns the scanned day whose fullness is closest to the target.
 *
 * Never throws and never returns null: on any error (e.g. missing params) it
 * returns minX.
 */
export function solveXForFullness(
  params: GrowthCurveParams,
  fullnessPct: number,
  options?: SolveXForFullnessOptions
): number {
  const minX = options?.minX ?? 0;

  try {
    const toleranceX = options?.toleranceX ?? 0.01;
    const maxIterations = options?.maxIterations ?? 200;
    const cycleLength = params.growth_mode === 'cyclical' ? params.cycle_length : null;
    const defaultMaxX = cycleLength != null && Number.isFinite(cycleLength) && cycleLength > 0 ? cycleLength : 3650;
    const maxX = options?.maxX ?? defaultMaxX;

    const target = fullnessPct / 100;
    const fullnessAt = (x: number) => {
      const value = evaluateGrowthCurve(params, x) / params.l;
      return Number.isFinite(value) ? value : 0;
    };

    let prevX = minX;
    const startValue = fullnessAt(minX);
    if (startValue >= target) {
      return minX;
    }

    let bestX = minX;
    let bestDiff = Math.abs(startValue - target);

    for (let step = 1; minX + step * SOLVE_SCAN_STEP_DAYS <= maxX + 1e-9; step += 1) {
      const x = minX + step * SOLVE_SCAN_STEP_DAYS;
      const value = fullnessAt(x);
      const diff = Math.abs(value - target);
      if (diff < bestDiff) {
        bestDiff = diff;
        bestX = x;
      }

      if (value >= target) {
        let lo = prevX;
        let hi = x;
        for (let i = 0; i < maxIterations && hi - lo > toleranceX; i += 1) {
          const mid = (lo + hi) / 2;
          if (fullnessAt(mid) < target) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        return (lo + hi) / 2;
      }

      prevX = x;
    }

    return bestX;
  } catch {
    return minX;
  }
}

// ---------------------------------------------------------------------------
// Inline tests. This project has no test runner configured (no jest/vitest,
// no *.test.* files anywhere), so these follow the Deno convention used by
// the edge functions themselves: run directly with
//   deno run supabase/functions/_shared/growth-curve.ts
// and guarded by `import.meta.main` so importing this module elsewhere never
// executes them.
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const approxEqual = (actual: number, expected: number, tolerance: number) =>
    Math.abs(actual - expected) <= tolerance;

  function check(name: string, actual: number, expected: number, tolerance: number) {
    const pass = approxEqual(actual, expected, tolerance);
    const status = pass ? 'PASS' : 'FAIL';
    console.log(`[${status}] ${name}: got ${actual.toFixed(4)}, expected ~${expected} (±${tolerance})`);
  }

  // The source PDF's reference table gives y(180) ≈ 941.87, but that value is
  // wrong: it's been independently hand-verified (and confirmed against x=45,
  // x=90, and x=120 as well) that the table contains multiple arithmetic
  // errors. Evaluating the equation directly, as implemented here, is the
  // ground truth — this test asserts against that (918.84), not the table.
  const annualBounded: GrowthCurveParams = {
    growth_mode: 'annual_bounded',
    l: 1000,
    k: 0.05,
    x0: 120,
    xg: 45,
    kg: 0.2,
    xs: 200,
    f: 0.9,
    ks: 0.03,
  };
  check('annual_bounded y(180) matches direct equation evaluation', evaluateGrowthCurve(annualBounded, 180), 918.84, 1);

  // Sanity checks that don't depend on the missing ks value:

  // Long before germination/growth, output should be ~0.
  check('annual_bounded y(0) ~ 0', evaluateGrowthCurve(annualBounded, 0), 0, 1);

  // Well past senescence, M(x) -> f, G(x) and P(x) -> 1, so y(x) -> L * f.
  check('annual_bounded y(2000) -> L*f', evaluateGrowthCurve(annualBounded, 2000), 1000 * 0.9, 0.5);

  // woody_residual: past xs, growth adds r*(x-xs) on top of L*G*P.
  const woodyResidual: GrowthCurveParams = {
    growth_mode: 'woody_residual',
    l: 1000,
    k: 0.05,
    x0: 120,
    xg: 45,
    kg: 0.2,
    xs: 200,
    r: 2,
  };
  // At x = xs, the residual term is exactly 0, so M(xs) = 1 and
  // y(xs) = L * G(xs) * P(xs).
  const gAtXs = 1 / (1 + Math.exp(-0.2 * (200 - 45)));
  const pAtXs = 1 / (1 + Math.exp(-0.05 * (200 - 120)));
  check('woody_residual y(xs) == L*G(xs)*P(xs)', evaluateGrowthCurve(woodyResidual, 200), 1000 * gAtXs * pAtXs, 0.01);

  // 300 days past xs, M = 1 + 2*300/1000 = 1.6, and G/P are both ~1 by then.
  check('woody_residual y(500) ~ L*1.6', evaluateGrowthCurve(woodyResidual, 500), 1000 * 1.6, 1);

  // cyclical: P(x) multiplies the seasonal term and is evaluated on raw x, so
  // y = L * G(x) * P(x) * M(x). At x = x0 the P term is exactly 0.5 and the
  // season's logistic is also 0.5.
  const cyclical: GrowthCurveParams = {
    growth_mode: 'cyclical',
    l: 500,
    k: 0.1,
    x0: 60,
    xg: 10,
    kg: 0.3,
    cycle_length: 365,
    b_base: 50,
    l_season: 450,
  };
  const gAt60 = 1 / (1 + Math.exp(-0.3 * (60 - 10)));
  const pAt60 = 0.5;
  check(
    'cyclical y(60) = L*G*P*M at season inflection',
    evaluateGrowthCurve(cyclical, 60),
    500 * gAt60 * pAt60 * (50 / 500 + 450 / 500 / 2),
    0.01
  );
  // One full cycle later the seasonal term wraps back to the same point, but
  // P(x) is on raw x (not periodic): P(425) = 1/(1+e^(-0.1*365)) ~ 1, not 0.5.
  const pAt425 = 1 / (1 + Math.exp(-0.1 * (60 + 365 - 60)));
  const gAt425 = 1 / (1 + Math.exp(-0.3 * (60 + 365 - 10)));
  check(
    'cyclical y(60 + cycle_length) uses raw-x P(x), so differs from y(60)',
    evaluateGrowthCurve(cyclical, 60 + 365),
    500 * gAt425 * pAt425 * (50 / 500 + 450 / 500 / 2),
    0.001
  );
  // Once P(x) has saturated, later cycles do repeat exactly.
  check(
    'cyclical y(x + cycle_length) matches y(x) once P(x) ~ 1',
    evaluateGrowthCurve(cyclical, 200 + 365),
    evaluateGrowthCurve(cyclical, 200),
    1
  );

  // solveXForFullness: round-trip against evaluateGrowthCurve for a mode
  // that's monotonic over the whole search range.
  const targetX = 300;
  const fullnessAtTargetX = (evaluateGrowthCurve(woodyResidual, targetX) / woodyResidual.l) * 100;
  const solvedX = solveXForFullness(woodyResidual, fullnessAtTargetX);
  check('solveXForFullness round-trips woody_residual', solvedX, targetX, 1);

  const fullnessPctAt = (params: GrowthCurveParams, x: number) => (evaluateGrowthCurve(params, x) / params.l) * 100;
  const checkInRange = (name: string, actual: number, min: number, max: number) => {
    const pass = actual >= min && actual <= max;
    console.log(`[${pass ? 'PASS' : 'FAIL'}] ${name}: got ${actual.toFixed(4)}, expected in [${min}, ${max}]`);
  };

  // woody_residual: a target at or below the day-0 fullness returns minX.
  check('solveXForFullness woody 0% returns minX', solveXForFullness(woodyResidual, 0), 0, 0);

  // annual_bounded: rises, then declines toward f after senescence. A target on
  // the rising side round-trips.
  const annualTargetX = 90;
  check(
    'solveXForFullness round-trips annual_bounded (rising side)',
    solveXForFullness(annualBounded, fullnessPctAt(annualBounded, annualTargetX)),
    annualTargetX,
    0.5
  );
  // annual_bounded: a target above the curve's peak is unreachable, so the
  // solver returns the closest day (the peak) instead of failing.
  const annualValues = Array.from({ length: 3651 }, (_, i) => evaluateGrowthCurve(annualBounded, i) / annualBounded.l);
  const annualPeakDay = annualValues.indexOf(Math.max(...annualValues));
  const annualClosestX = solveXForFullness(annualBounded, 100);
  checkInRange('solveXForFullness annual_bounded unreachable returns the peak day', annualClosestX, annualPeakDay - 1, annualPeakDay + 1);

  // cyclical: l=450, k=0.15, x0=20, 50% target. The curve reaches 50% around
  // day 25; day 3650 sits at the start of a cycle (~15%), which used to make
  // the solver return 3650.
  const cyclicalRegression: GrowthCurveParams = {
    growth_mode: 'cyclical',
    l: 450,
    k: 0.15,
    x0: 20,
    xg: 0,
    kg: 0.2,
    cycle_length: 365,
    b_base: 50,
    l_season: 400,
  };
  const cyclicalSolved = solveXForFullness(cyclicalRegression, 50);
  checkInRange('solveXForFullness cyclical 50% target is ~day 15-30', cyclicalSolved, 15, 30);
  check('solveXForFullness cyclical result evaluates to 50%', fullnessPctAt(cyclicalRegression, cyclicalSolved), 50, 0.5);

  // Never fails: odd targets on every mode return finite numbers.
  for (const [label, params] of [
    ['annual_bounded', annualBounded],
    ['woody_residual', woodyResidual],
    ['cyclical', cyclicalRegression],
  ] as const) {
    for (const pct of [-10, 0, 100, 250]) {
      const x = solveXForFullness(params, pct);
      console.log(`[${Number.isFinite(x) ? 'PASS' : 'FAIL'}] solveXForFullness ${label} ${pct}% is finite: ${x}`);
    }
  }

  // Missing required params must not throw; falls back to minX.
  const brokenCyclical = { ...cyclicalRegression, b_base: null } as GrowthCurveParams;
  check('solveXForFullness with missing params returns minX', solveXForFullness(brokenCyclical, 50), 0, 0);
}
